import{_ as a,o as t,c as o,a2 as i}from"./chunks/framework.DgAozdHm.js";const u=JSON.parse('{"title":"IP 国家库","description":"","frontmatter":{},"headers":[],"relativePath":"guide/geoip.md","filePath":"guide/geoip.md","lastUpdated":1793370509000}'),s={name:"guide/geoip.md"};function d(n,e,r,l,p,c){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="ip-国家库" tabindex="-1">IP 国家库 <a class="header-anchor" href="#ip-国家库" aria-label="Permalink to &quot;IP 国家库&quot;">​</a></h1><p>面板优先读取 MaxMind GeoLite2 Country 数据库，用于在新建或编辑服务器时自动填写国家/地区。</p><h2 id="镜像内置" tabindex="-1">镜像内置 <a class="header-anchor" href="#镜像内置" aria-label="Permalink to &quot;镜像内置&quot;">​</a></h2><p>后端镜像在构建时下载固定版本的 <code>GeoLite2-Country.mmdb</code>，并校验 SHA-256，运行路径为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/usr/share/hoplane/GeoLite2-Country.mmdb</span></span></code></pre></div><p>GeoLite2 data created by MaxMind, available from <a href="https://www.maxmind.com" target="_blank" rel="noreferrer">https://www.maxmind.com</a>.</p><h2 id="覆盖路径" tabindex="-1">覆盖路径 <a class="header-anchor" href="#覆盖路径" aria-label="Permalink to &quot;覆盖路径&quot;">​</a></h2><p>如需使用自己的数据库，设置：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HOPLANE_GEOIP_MMDB=/path/to/GeoLite2-Country.mmdb</span></span></code></pre></div><h2 id="其他来源" tabindex="-1">其他来源 <a class="header-anchor" href="#其他来源" aria-label="Permalink to &quot;其他来源&quot;">​</a></h2><p>未找到 MMDB 时，面板会依次尝试：</p><ol><li><code>HOPLANE_GEOIP_CSV</code> 指定的 <code>cidr,country</code> CSV；</li><li><code>HOPLANE_GEOIP_URL</code> 指定的 HTTP 查询服务；</li><li>按节点名称推断国旗。</li></ol>',12)])])}const m=a(s,[["render",d]]);export{u as __pageData,m as default};
